1	// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
2	// engine tree vendors wholesale on every converge; a pack's directory ships only
3	// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`. So a
4	// canon commit that edits `packs/<id>/` without moving that number reaches no member —
5	// the fleet keeps the old bytes while the canon believes the change shipped (#939
6	// froze seven repos for five days that way), and two changes landing under ONE
7	// number strand whichever members converged between them (#1482).
8	//
9	// So the number is not the pull request's to move. It is read off `main` after the
10	// fact: this module walks a pack's history on the base branch, finds the commit that
11	// last moved its version, and asks whether any SHIPPING byte under `packs/<id>/` has
12	// changed since. Every such pack takes the next version cut today, in one commit,
13	// from one writer — which is what makes a collision impossible rather than merely
14	// checked for. The same walk, read the other way round, says which pull requests each
15	// version carried, which is what the version-history rows are made of.
16	//
17	// Both readers are here so the two tasks that need them — the bump on every push to
18	// main, and the weekly history — cannot disagree about what a bump or a shipping file
19	// is. Pure over a `git` runner the caller hands in, so the tests drive them against a
20	// scratch repository and the workers against the real one.
21	
22	import { LOCAL_PACKS_SUBDIR } from '../../engine/pack_loader/pack-registry.mjs';
23	import {
24	  VERSION_SOURCE, versionFromLiteral, compareVersions, versionsEqual, nextVersion, versionAbove,
25	} from '../../engine/version.mjs';
26	
27	// The pack-shelf root the engine reads a canon's packs from, and the one tree this
28	// module ever looks at. A repo's OWN packs are neither versioned nor vendored, so
29	// nothing about them is a delivery question.
30	export const SHELF = 'packs';
31	const LOCAL_ROOT = `${LOCAL_PACKS_SUBDIR}/`;
32	
33	// Each pack's version-history record, next to its manifest.
34	export const VERSIONS_FILENAME = 'VERSIONS.md';
35	
36	// The task that writes bump commits, named where the commit is stamped and where the
37	// history reads the stamp back: a bump commit moves only version numbers, so it is
38	// never something a version "shipped".
39	export const BUMP_TASK = 'claudinite-canon-curation/pack-version-bump';
40	
41	// Does this path ride a pack's directory copy to a member? A pack's tests sit beside
42	// the files they cover and are the one thing in that directory no vendor set carries
43	// (compute-vendor-set drops `*.test.mjs`), so nobody is waiting on them. `VERSIONS.md`
44	// is the record OF versions, not content a version ships, so a row landing must never
45	// itself demand another version.
46	export function isShippingFile(path) {
47	  if (path.startsWith(LOCAL_ROOT)) return false;
48	  if (path.endsWith('.test.mjs') || path.endsWith(`/${VERSIONS_FILENAME}`)) return false;
49	  return /^packs\/[^/]+\//.test(path);
50	}
51	
52	// The pack id a shipping path belongs to, or null.
53	export function packOf(path) {
54	  const m = /^packs\/([^/]+)\//.exec(path);
55	  return m ? m[1] : null;
56	}
