58	// The `version:` a pack manifest declares, or null when it declares none (a manifest
59	// absent on one side of the history, or one the schema check owns). The preceding
60	// character class is what keeps `minEngineVersion:` out of it.
61	const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[\s{,])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
