63	  const m = PACK_VERSION_RE.exec(text ?? '');
64	  return m ? versionFromLiteral(m[1]) : null;
65	}
66	
67	// The manifest text with its `version:` literal replaced — and nothing else moved,
68	// so the commit that bumps a pack is a one-line diff on a file people edit by hand.
69	export function withPackVersion(text, version) {
70	  return text.replace(PACK_VERSION_RE, (whole, old) => whole.replace(old, String(version)));
71	}
72	
73	// --- reading the shelf --------------------------------------------------------
74	
75	// The pack ids whose manifest exists at `ref`, from the tree rather than the
76	// working directory: the checkout may be sitting on another task's branch.
77	export function shelfPacks(git, ref) {
78	  const paths = git(['ls-tree', '--name-only', '-r', ref, `${SHELF}/`]).split('\n');
79	  return paths.map((p) => /^packs\/([^/]+)\/pack\.mjs$/.exec(p)?.[1]).filter(Boolean).sort();
80	}
81	
82	export function fileAt(git, ref, path) {
83	  try { return git(['show', `${ref}:${path}`]); } catch { return null; }
84	}
85	
86	// Every commit on the base branch's first-parent line that MOVED this pack's version
87	// — the commit's own manifest declares a version its first parent did not — newest
88	// first, each as `{ sha, version, date }` (`date` the committer date, `YYYY-MM-DD`).
89	// A pack's first commit counts: its first version shipped to everyone. Every squash
