1	// The pack-version-bump entry point: cut a new version for every pack on the shelf
2	// whose shipping content moved since its version last did, in one commit straight
3	// onto the base branch. Run by the canon's push-to-main workflow the moment a merge
4	// lands, and as this task's daily code-work for the merges GitHub turns into no push
5	// run (a pull request the queue lands with the Action's own token).
6	//
7	// The decision — which packs, which numbers — is `../../pack-versions.mjs`; this
8	// file is the I/O shell around it: fetch the base tip with enough history to find
9	// each pack's last bump, commit the new manifests onto that tip with git plumbing,
10	// push without force, and try again from the new tip when the branch moved under
11	// the push. Nothing here touches the checkout: one executor run drains several items
12	// from one working tree, so the commit is built in a throwaway index against the
13	// fetched tip, exactly as the generated-file lane does.
14	
15	import { execFileSync } from 'node:child_process';
16	import { rmSync } from 'node:fs';
17	import { tmpdir } from 'node:os';
18	import { join } from 'node:path';
19	import { pathToFileURL } from 'node:url';
20	import { remoteUrl, withTaskTrailer } from '../../../claudinite-tasks/shared-code/delivery.mjs';
21	import { planBumps, bumpSubject, BUMP_TASK } from '../../pack-versions.mjs';
22	
23	const item = process.env.CLAUDINITE_ITEM || '';
24	const log = (s) => console.log(`pack-version-bump${item ? ` [#${item}]` : ''}: ${s}`);
25	
26	export const makeGit = (root) => (args, opts = {}) => execFileSync('git', ['-C', root, ...args], {
27	  encoding: 'utf8',
28	  stdio: [opts.input === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'],
29	  ...opts,
30	});
31	
32	// The base branch's remote tip, with the whole first-parent history behind it: the
33	// walk stops at each pack's last bump, which for a quiet pack can be months back,
34	// and an Actions checkout is one commit deep. Unshallowing is a fetch the size of the
35	// repository once and a no-op after; on a complete clone the plain fetch is enough.
36	export function fetchBase(git, remote, base) {
37	  const shallow = git(['rev-parse', '--is-shallow-repository']).trim() === 'true';
38	  git(['fetch', '--quiet', ...(shallow ? ['--unshallow'] : []), remote, base]);
39	  return git(['rev-parse', 'FETCH_HEAD']).trim();
40	}
41	
42	// Commit `files` ({ path: content }) onto `baseSha` and push the result to `branch`
43	// as a fast-forward. Returns the commit, or null when the remote refused the push
44	// because the branch had moved — the caller replans from the new tip.
45	export function pushOnto(git, { remote, baseSha, branch, files, message }) {
46	  const index = join(tmpdir(), `claudinite-bump-${process.pid}-${Date.now()}.index`);
47	  const plumb = (args, opts) => git(args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
48	  try {
49	    plumb(['read-tree', baseSha]);
50	    for (const [path, content] of Object.entries(files)) {
51	      const blob = git(['hash-object', '-w', '--stdin'], { input: content }).trim();
52	      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
53	    }
54	    const tree = plumb(['write-tree']).trim();
55	    const commit = git([
56	      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
57	      'commit-tree', tree, '-p', baseSha, '-m', message,
58	    ]).trim();
59	    try {
60	      git(['push', '--quiet', remote, `${commit}:refs/heads/${branch}`]);
61	    } catch (e) {
62	      if (/rejected|fetch first|non-fast-forward|stale info/i.test(String(e.stderr ?? e.message))) return null;
63	      throw e;
64	    }
65	    return commit;
66	  } finally { rmSync(index, { force: true }); }
67	}
68	
69	// One pass: plan against the fetched tip, commit, push. `attempts` bounds the replans
70	// a moving base branch can cost; a busy canon lands a handful of merges an hour, so
71	// three is generous and a fourth rejection is worth a red run. `git` is injectable
72	// so a test can move the branch between the plan and the push.
73	export async function run({ root, remote, base, today = new Date(), attempts = 3, log: say = log, git = makeGit(root) }) {
74	  for (let attempt = 1; attempt <= attempts; attempt += 1) {
75	    const tip = fetchBase(git, remote, base);
76	    const bumps = planBumps(git, tip, { today });
77	    if (!bumps.length) {
78	      say(`${base} at ${tip.slice(0, 10)}: every pack's version already covers its content — nothing to bump`);
79	      return { bumped: [], commit: null };
80	    }
81	    for (const b of bumps) say(`${b.id}: ${b.from} → ${b.to} (${b.changed.length} shipping file(s) changed since ${b.from})`);
82	    const files = Object.fromEntries(bumps.map((b) => [b.manifest, b.text]));
83	    const commit = pushOnto(git, { remote, baseSha: tip, branch: base, files, message: withTaskTrailer(bumpSubject(bumps), BUMP_TASK) });
84	    if (commit) {
85	      say(`pushed ${commit.slice(0, 10)} onto ${base}`);
86	      return { bumped: bumps.map((b) => ({ id: b.id, from: b.from, to: b.to })), commit };
87	    }
88	    say(`${base} moved under the push (attempt ${attempt} of ${attempts}) — replanning from its new tip`);
89	  }
90	  throw new Error(`${base} kept moving under ${attempts} pushes — run again`);
91	}
92	
93	export async function main() {
94	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
95	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
96	  const token = process.env.GITHUB_TOKEN;
97	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
98	  if (!repo) throw new Error('CLAUDINITE_REPO / GITHUB_REPOSITORY is not set (owner/repo)');
99	  if (!token) throw new Error('GITHUB_TOKEN is not set — the bump cannot push to the base branch');
100	  await run({ root, remote: remoteUrl(repo, token), base });
101	}
102	
103	// Run only when invoked directly (`node worker.mjs`), never on import.
104	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
105	  main().catch((e) => { console.error(`pack-version-bump failed: ${e.message}`); process.exit(1); });
106	}

